include <robotics.scad>
// RPLIDAR S2 base housing. Origin = centre of bottom mounting face.
W = 77;          // base width/depth (official)
H = 20.8;        // base height (datasheet v2.4)
ch = 12;         // corner chamfer leg, scaled from drawing (NOT dimensioned)
r  = 3;          // corner softening (NOT dimensioned)
hole_sp = 41.7;  // M3 square pattern (official)
hole_d = 2.5;    // M3 tap-drill (thread minor) representation
hole_depth = 4;  // official max engagement
module outline() {
  offset(r = r) offset(delta = -r)
    polygon([[-W/2+ch,-W/2],[W/2-ch,-W/2],[W/2,-W/2+ch],[W/2,W/2-ch],
             [W/2-ch,W/2],[-W/2+ch,W/2],[-W/2,W/2-ch],[-W/2,-W/2+ch]]);
}
difference() {
  hull() {                       // small 1 mm chamfers on top and bottom edges
    translate([0,0,1]) linear_extrude(H-2) outline();
    linear_extrude(H) offset(delta=-1) outline();
  }
  for (x=[-1,1], y=[-1,1])
    translate([x*hole_sp/2, y*hole_sp/2, -0.01]) cylinder(d=hole_d, h=hole_depth+0.01, $fn=32);
}

include <robotics.scad>
// Optical window enclosure. Origin = centre of its bottom face (base top).
D = 71;    // scaled from drawing, NOT dimensioned
H = 19;    // official (39.8 - 20.8)
cyl(d = D, h = H, rounding2 = 4, anchor = BOT, $fn = 96);

include <robotics.scad>
// Strain relief boss. Origin = on rear face of base, at cable axis.
L = 3.6;   // official protrusion (80.6 - 77)
w = 7;     // scaled, NOT dimensioned
h = 5;     // scaled, NOT dimensioned
cuboid([w, L + 0.5, h], rounding = 1, edges = "Y", anchor = FRONT, $fn = 24, spin = 0) ;
